HISTORY_ID='bbd44e69cb8906b502d7159079e24eb7'

def wait_dataset(dataset_id, timeout=3600, poll=5):
    start=time.time()
    while time.time()-start<timeout:
        try:
            d=gi.datasets.show_dataset(dataset_id)
        except Exception as e:
            if '429' in str(e) or 'Too Many Requests' in str(e):
                time.sleep(poll*2); continue
            raise
        state=d.get('state')
        if state in ('ok','error','failed_metadata','empty','discarded'):
            return d
        time.sleep(poll)
    raise RuntimeError(f'timeout dataset {dataset_id}')

def wait_history_jobs(history_id, timeout=3600, poll=5):
    # Wait until no jobs in new/queued/running for this history.
    start=time.time()
    while time.time()-start<timeout:
        try:
            jobs=gi.jobs.get_jobs(history_id=history_id)
        except Exception as e:
            if '429' in str(e): time.sleep(poll*2); continue
            raise
        active=[j for j in jobs if j.get('state') in ('new','queued','running','upload')]
        if not active and jobs:
            return jobs
        time.sleep(poll)
    raise RuntimeError('timeout jobs')

def run_tool(tool_id, inputs, wait=True, timeout=3600, poll=5):
    last=None
    for attempt in range(8):
        try:
            res=gi.tools.run_tool(HISTORY_ID, tool_id=tool_id, tool_inputs=inputs, input_format='legacy')
            print('run_tool response:', res)
            break
        except Exception as e:
            s=str(e)
            if '429' in s or 'Too Many Requests' in s:
                time.sleep(min(60, 5*(attempt+1)))
                last=e; continue
            raise
    else:
        raise last
    if not wait:
        return res
    # collect output dataset ids from response
    out_ids=[]
    def walk(x):
        if isinstance(x,dict):
            if x.get('model_class')=='Dataset' or (x.get('id') and x.get('src')):
                if x.get('id'): out_ids.append(x['id'])
            for v in x.values(): walk(v)
        elif isinstance(x,list):
            for v in x: walk(v)
    walk(res)
    if not out_ids:
        # fallback: wait history jobs and find new outputs via contents
        wait_history_jobs(HISTORY_ID, timeout=timeout, poll=poll)
        cont=gi.histories.show_history(HISTORY_ID, contents=True)
        # return all ok datasets maybe
        return res
    outs={}
    for oid in out_ids:
        try:
            d=wait_dataset(oid, timeout=timeout, poll=poll)
            outs[oid]=d
        except Exception as e:
            outs[oid]={'error':str(e)}
    return {'tool_result':res,'outputs':outs}
